WITH filtered AS (SELECT id, order_id, method, amount, paid_at, status, ROUND(amount, 2) AS amount_rounded FROM payments WHERE paid_at > TIMESTAMP '2024-03-04 14:00:00'), flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM filtered), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT status, MIN(paid_at) AS first_paid_at, APPROX_PERCENTILE(burst_id, ARRAY(0.25, 0.5, 0.75)) AS burst_id_quartiles, SUM(amount) AS total_amount FROM islands GROUP BY CUBE (status) ORDER BY total_amount ASC NULLS LAST;
